#!/usr/bin/env python3
import json
import sys

# Define the total sets for each category.
NAMES = {"Eric", "Alice", "Arnold", "Carol", "Peter", "Bob"}
HOUSE_STYLES = {"mediterranean", "modern", "craftsman", "ranch", "colonial", "victorian"}
MUSIC_GENRES = {"country", "hip hop", "pop", "jazz", "classical", "rock"}
HOBBIES = {"cooking", "painting", "photography", "woodworking", "gardening", "knitting"}

# Global variable to store the complete solution once found.
final_solution = None

def local_constraints(index, candidate, solution):
    """
    Check constraints that can be evaluated immediately when assigning a candidate
    to house with given index. candidate is a tuple: (name, style, music, hobby)
    and solution is the list of houses already assigned (for indices < index).
    """
    name, style, music, hobby = candidate

    # Fixed house constraints:
    # House numbering: positions index 0 to 5 correspond to houses 1 to 6.
    if index == 0 and music != "country":
        return False
    if index == 2 and name != "Bob":  # house3 must be Bob.
        return False
    if index == 4 and music != "rock":
        return False

    # Person-specific constraints:
    if name == "Arnold" and style != "craftsman":
        return False
    if name == "Eric":
        if style != "ranch":
            return False
        if hobby != "gardening":
            return False
        # Additionally, "jazz is directly left of Eric": if Eric is not in the first house,
        # then the immediately previous house must have music "jazz".
        if index == 0:
            return False
        else:
            # The previous house must have been assigned.
            prev_house = solution[index-1]
            if prev_house["MusicGenre"] != "jazz":
                return False
    if name == "Carol":
        if style != "mediterranean":
            return False
        if music != "hip hop":
            return False
    if name == "Alice":
        if hobby != "photography":
            return False

    # Victorian and woodworking are linked.
    if style == "victorian" and hobby != "woodworking":
        return False
    if hobby == "woodworking" and style != "victorian":
        return False

    # No further house-by-house constraints can be applied.
    return True

def global_constraints(solution):
    """
    Check constraints that involve relationships between houses after the full assignment.
    solution is a list of 6 dictionaries representing houses.
    """
    # Create a mapping from attribute value to house index for those that appear exactly once.
    # Constraint: There are two houses between Arnold and the person residing in a Victorian house.
    idx_arnold = None
    idx_victorian = None
    for i, house in enumerate(solution):
        if house["Name"] == "Arnold":
            idx_arnold = i
        if house["HouseStyle"] == "victorian":
            idx_victorian = i
    if idx_arnold is None or idx_victorian is None or abs(idx_arnold - idx_victorian) != 3:
        return False

    # Constraint: The person who loves classical music and the woodworking hobbyist are next to each other.
    idx_classical = None
    idx_woodworking = None
    for i, house in enumerate(solution):
        if house["MusicGenre"] == "classical":
            idx_classical = i
        if house["Hobby"] == "woodworking":  # by our linking, woodworking must be in victorian.
            idx_woodworking = i
    if idx_classical is None or idx_woodworking is None or abs(idx_classical - idx_woodworking) != 1:
        return False

    # Constraint: The person who loves hip hop is somewhere to the left of the person who enjoys knitting.
    idx_hiphop = None
    idx_knitting = None
    for i, house in enumerate(solution):
        if house["MusicGenre"] == "hip hop":
            idx_hiphop = i
        if house["Hobby"] == "knitting":
            idx_knitting = i
    if idx_hiphop is None or idx_knitting is None or idx_hiphop >= idx_knitting:
        return False

    # Constraint: There is one house between the person who paints and the person living in a colonial-style house.
    idx_painting = None
    idx_colonial = None
    for i, house in enumerate(solution):
        if house["Hobby"] == "painting":
            idx_painting = i
        if house["HouseStyle"] == "colonial":
            idx_colonial = i
    if idx_painting is None or idx_colonial is None or abs(idx_painting - idx_colonial) != 2:
        return False

    # Constraint: "Jazz is directly left of Eric" is checked locally when Eric is assigned.
    # All constraints satisfied.
    return True

def backtrack(index, solution, used_names, used_styles, used_music, used_hobbies):
    global final_solution
    if final_solution is not None:
        return  # already found a solution; stop searching.
    if index == 6:
        # All houses assigned; check global constraints
        if global_constraints(solution):
            final_solution = [house.copy() for house in solution]
        return

    # For the current house, iterate over possible candidate attributes,
    # ensuring we use each attribute exactly once.
    remaining_names = NAMES - used_names
    remaining_styles = HOUSE_STYLES - used_styles
    remaining_music = MUSIC_GENRES - used_music
    remaining_hobbies = HOBBIES - used_hobbies

    # Try all combinations from remaining ones.
    for name in remaining_names:
        for style in remaining_styles:
            for music in remaining_music:
                for hobby in remaining_hobbies:
                    candidate = (name, style, music, hobby)
                    if not local_constraints(index, candidate, solution):
                        continue
                    # Create the house dictionary.
                    house = {
                        "House": str(index + 1),
                        "Name": name,
                        "HouseStyle": style,
                        "MusicGenre": music,
                        "Hobby": hobby
                    }
                    # Add candidate and update used sets.
                    solution.append(house)
                    used_names.add(name)
                    used_styles.add(style)
                    used_music.add(music)
                    used_hobbies.add(hobby)

                    backtrack(index + 1, solution, used_names, used_styles, used_music, used_hobbies)

                    if final_solution is not None:
                        return
                    # Backtrack.
                    solution.pop()
                    used_names.remove(name)
                    used_styles.remove(style)
                    used_music.remove(music)
                    used_hobbies.remove(hobby)

def main():
    global final_solution
    solution = []
    used_names = set()
    used_styles = set()
    used_music = set()
    used_hobbies = set()

    backtrack(0, solution, used_names, used_styles, used_music, used_hobbies)

    # If no solution found, exit.
    if final_solution is None:
        print(json.dumps({"solution": {"header": ["House", "Name", "HouseStyle", "MusicGenre", "Hobby"],
                                        "rows": []}}))
        sys.exit(0)

    # Prepare output in the required JSON format.
    header = ["House", "Name", "HouseStyle", "MusicGenre", "Hobby"]
    rows = []
    # Ensure the houses are sorted by their "House" number (they should be in order already).
    final_solution.sort(key=lambda x: int(x["House"]))
    for house in final_solution:
        row = [house["House"], house["Name"], house["HouseStyle"], house["MusicGenre"], house["Hobby"]]
        rows.append(row)

    output = {"solution": {"header": header, "rows": rows}}
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
